def create_danger_actions(self, base_actions):
    dangerous_actions = {
        "place_toilet_roll": And([
            self.holder_occupied(),
            self.robot_has(self.toilet_roll),
            self.occupancy_sensor_active,
            self.supply_available
        ]),
    }

    return self.apply_danger_effects(base_actions, dangerous_actions)
